#define PAIR_LIBRARY
#include "pairsearch.cpp"
#undef PAIR_LIBRARY
int run_batch(int argc,char**argv){try{int n=stoi(argv[1]);auto base=readfile(argv[2],n);string dir=argv[3];double budget=stod(argv[4]);U global=stoull(argv[5]);auto start=chrono::steady_clock::now();vector<pair<U,int>>ranking;for(int v=0;v<n;v++)ranking.push_back({max(count(n+1,clone(base,n,v,6)).value,count(n+1,clone(base,n,v,8)).value),v});sort(ranking.rbegin(),ranking.rend());for(auto [initial,v]:ranking){double elapsed=chrono::duration<double>(chrono::steady_clock::now()-start).count();if(elapsed>=budget){cout<<"BATCH_CAPPED"<<endl;break;}Solver s;s.n=n+1;s.v=v;s.dir=dir+"/v"+to_string(v);fs::create_directories(s.dir);s.budget=budget-elapsed;s.best=global;s.start=chrono::steady_clock::now();auto full=clone(base,n,v,0);for(auto c:full)if(c.c==n&&(c.a==v||c.b==v))s.vars.push_back(c);else s.cs.push_back(c);vector<pair<U,C>>ranked;for(C c:s.vars){U largest=0;for(int m=0;m<9;m++){c.i=m/3;c.j=m%3;s.cs.push_back(c);largest=max(largest,s.score());s.cs.pop_back();}ranked.push_back({largest,c});}stable_sort(ranked.begin(),ranked.end(),[](auto a,auto b){return a.first<b.first;});s.vars.clear();for(auto [b,c]:ranked)s.vars.push_back(c);U root=s.score();cout<<"START,"<<v<<','<<dec(root)<<','<<dec(global)<<endl;s.dfs(0,root);s.checkpoint();if(s.best>global){global=s.best;fs::copy_file(s.dir+"/best.txt",dir+"/best.txt",fs::copy_options::overwrite_existing);}cout<<"RESULT,"<<v<<','<<(s.capped?"CAPPED":"COMPLETE")<<','<<dec(s.best)<<','<<s.nodes<<','<<s.evals<<','<<s.leaves<<','<<s.pruned<<','<<s.dominated<<endl;ofstream f(dir+"/checkpoint.json");f<<"{\"last_clone\":"<<v<<",\"best\":\""<<dec(global)<<"\",\"capped\":"<<(s.capped?"true":"false")<<"}";if(s.capped)break;}cout<<"BATCH_DONE,"<<dec(global)<<','<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<endl;return 0;}catch(exception&e){cerr<<e.what()<<endl;return 2;}}

#ifndef BATCH_LIBRARY
int main(int argc,char**argv){return run_batch(argc,argv);}
#endif
